mapper.insert:
INSERT INTO MBR (
       MBR_STTS_CD
     , MBR_AUTHRT_CD
     , JOIN_PATH_CD
     , ACNT_EML_ENC
     , ACNT_EML_HMAC
     , MBL_TELNO_ENC
     , MBL_TELNO_HMAC
     , PSWD_HASH
     , MBR_NCNM
     , NCNM_STNG_CMPTN_YN
) VALUES (
       #{mbrSttsCd}
     , #{mbrAuthrtCd}
     , #{joinPathCd}
     , #{acntEmlEnc}
     , #{acntEmlHmac}
     , #{mblTelnoEnc}
     , #{mblTelnoHmac}
     , #{pswdHash}
     , #{mbrNcnm}
     , 'N'
)

INSERT INTO MBR_STTS_HSTRY (
       MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
) VALUES (
       #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
)

mapper.update:
UPDATE MBR
   SET MBR_NCNM = #{mbrNcnm}
     , NCNM_STNG_CMPTN_YN = 'Y'
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}

/* 최근 로그인 일시 갱신 */
UPDATE MBR
   SET LAST_LGN_DT = NOW()
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}

mapper.select:
/* 탈퇴 보관일수 경과 회원 번호 조회 */
SELECT MBR_SN
  FROM MBR
 WHERE MBR_STTS_CD = #{mbrSttsCd}
   AND WHDWL_DT IS NOT NULL
   AND WHDWL_DT < DATE_SUB(NOW(), INTERVAL #{keepDayCnt} DAY)
